1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.jdbc.support.GeneratedKeyHolder;
7	import org.springframework.jdbc.support.KeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	/** Data access for {@link Invoice} rows (JdbcTemplate over the schema in V4__invoices.sql). */
11	@Repository
12	public class InvoiceRepository {
13	
14	    private final JdbcTemplate jdbc;
15	
16	    public InvoiceRepository(JdbcTemplate jdbc) {
17	        this.jdbc = jdbc;
18	    }
19	
20	    private static final org.springframework.jdbc.core.RowMapper<Invoice> MAPPER =
21	            (rs, i) -> new Invoice(rs.getLong("id"), rs.getLong("project_id"),
22	                    rs.getBigDecimal("amount"), rs.getString("status"),
23	                    rs.getString("issued_date"), rs.getString("due_date"));
24	
25	    // An invoice's amount is the sum of its line items (qty * unit_price); a line-item-less invoice
26	    // totals zero. Derived here so the amount always reflects the current line items.
27	    private static final String AMOUNT_SUM =
28	            "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li"
29	                    + " WHERE li.invoice_id = i.id), 0)";
30	
31	    public List<Invoice> findByProject(long projectId) {
32	        return jdbc.query(
33	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, i.status, i.issued_date,"
34	                        + " i.due_date FROM invoices i WHERE i.project_id = ? ORDER BY i.id",
35	                MAPPER, projectId);
36	    }
37	
38	    /** A project's invoices ordered by due date, earliest first (nulls last, id as tiebreak). */
39	    public List<Invoice> findByProjectOrderByDueDate(long projectId) {
40	        return jdbc.query(
41	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, i.status, i.issued_date,"
42	                        + " i.due_date FROM invoices i WHERE i.project_id = ?"
43	                        + " ORDER BY i.due_date ASC NULLS LAST, i.id",
44	                MAPPER, projectId);
45	    }
